import "./Product.css";

function Product() {
  const { id } = useParams();
  const [prod, setProd] = useState([]);
  useEffect(() => {
    fetch("https://dummyjson.com/products")
      .then((res) => res.json())
      .then((res) => setProd(res.products));
  }, []);

  const productData = prod.filter((elm) => elm.id === Number(id))[0];

